/* From Uiverse.io by AnthonyPreite - Tags: red, green, minimalist, checkbox */
/* ni means name input*/

.__UIV_SCOPE__ .ni {
  font-size: 16px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s ease;
  padding: 8px 20px;
  border-radius: .8rem;
  min-width: 124px;
  text-align: center;
  background: rgba(78, 190, 150, 0.1);
  border: 0.5px solid rgba(22, 179, 124, 0.2);
  cursor: pointer;
}

.__UIV_SCOPE__ .ni:before {
  content: "Check";
  color: #4EBE96;
}

.__UIV_SCOPE__ .ni:active {
  transform: scale(0.94);
}

.__UIV_SCOPE__ #ni {
  position: fixed;
  opacity: 0;
  visibility: hidden;
}

.__UIV_SCOPE__ #ni:checked + .ni {
  background: rgba(216, 79, 104, 0.1);
  border-color: rgba(216, 79, 104, 0.2);
}

.__UIV_SCOPE__ #ni:checked + .ni:before {
  content: "Uncheck";
  color: #D84F68;
}
